export class ElementCache {
    constructor() {
        this.cache = {};
    }
    /**
     * This extension allows you to easily cache the newly created element.
     * @param elementCache - A hash map of where to cache the element.
     * @param key - The name off the variable to cache.
     * @returns
     */
    assignTo(key) {
        return (element) => {
            this.cache[key] = element;
        };
    }
    set(key, element) {
        if (element != null) {
            this.cache[key] = element;
        }
        else {
            delete this.cache[key];
        }
    }
    //Only gets the element if it is attached to the DOM.
    get(key) {
        const element = this.cache[key];
        if (element != null && element.isConnected) {
            return element;
        }
    }
}
